<script setup>
import ChatPortrait from './ChatPortrait.vue';
defineProps({ model: Object });
const roles = { leader: '團長', deputy: '副團長', member: '成員' };
</script>
<template>
  <template v-if="['preview', 'members'].includes(model.kind)">
    <template v-for="person in model.items" :key="person.id">
      <div v-if="model.kind === 'preview'" class="expedition-preview-person"><ChatPortrait class="expedition-preview-avatar" :name="person.nickname" :url="person.avatar_url" /><strong>{{ person.nickname }}{{ person.id === model.uid ? '（你）' : '' }}</strong><button v-if="person.id !== model.uid" type="button" class="member-options-button" :data-preview-person="person.id" :aria-label="`${person.nickname}的成員選項`">⋯</button></div>
      <article v-else class="expedition-managed-person"><div class="expedition-preview-person"><ChatPortrait class="expedition-preview-avatar" :name="person.nickname" :url="person.avatar_url" /><strong :title="person.nickname">{{ person.nickname }}{{ person.id === model.uid ? '（你）' : '' }}<small>{{ roles[person.role] || '成員' }}</small></strong></div><div class="expedition-member-actions"><button v-if="person.can_set_role" type="button" :data-member-role="person.id" :disabled="model.busy">{{ person.role === 'deputy' ? '取消副團長' : '設為副團長' }}</button><button v-if="person.can_kick" type="button" :data-member-kick="person.id" :disabled="model.busy">移除成員</button></div><div v-if="model.pending?.id === person.id" class="expedition-member-confirm"><p>{{ model.pending.kind === 'kick' ? `移除「${person.nickname}」？對方將退出遠征隊與小隊，未完成任務會撤回，已接任務會釋出。` : `${person.role === 'deputy' ? '取消' : '指派'}「${person.nickname}」的副團長權限？` }}</p><button type="button" class="button secondary" data-member-confirm :disabled="model.busy">{{ model.busy ? '處理中…' : '確認' }}</button><button type="button" class="button outline" data-member-cancel :disabled="model.busy">取消</button></div></article>
    </template><p v-if="!model.items.length && !model.loading" class="expedition-preview-empty">目前沒有成員。</p>
  </template>
  <template v-else-if="model.kind === 'admin'">
    <article v-for="person in model.items" :key="person.id" class="site-admin-person"><div><strong>{{ person.nickname }}<span v-if="person.is_admin" class="expedition-current">管理員</span></strong><p>@{{ person.username }} · {{ person.suspended ? '已停用' : '使用中' }}</p><small>{{ person.registered ? '註冊於 ' + new Date(person.registered * 1000).toLocaleDateString('zh-TW') : '' }}</small></div><button v-if="!person.is_admin" type="button" class="button outline" :class="{ 'logout-button': !person.suspended }" :data-admin-toggle="person.id" :disabled="model.busy || model.loading">{{ person.suspended ? '恢復帳號' : '停用帳號' }}</button><div v-if="model.pending === person.id" class="site-admin-confirm"><p>{{ person.suspended ? `恢復「${person.nickname}」？對方可再次登入。` : `停用「${person.nickname}」？將強制登出所有裝置並停止位置分享。既有資料保留，可隨時恢復帳號。` }}</p><button class="button secondary" type="button" data-admin-confirm :disabled="model.busy">{{ model.busy ? '處理中…' : '確認' }}</button><button class="button outline" type="button" data-admin-cancel :disabled="model.busy">取消</button></div></article><p v-if="!model.items.length && !model.loading" class="expedition-preview-empty">沒有符合的帳號。</p>
  </template>
  <template v-else-if="model.kind === 'personOptions'"><div class="expedition-person-options"><button type="button" class="button outline" data-person-action="friend" :disabled="!model.data.can_friend || model.busy">申請好友</button><button type="button" class="button outline" data-person-action="block" :disabled="model.busy">{{ model.data.blocked_by_me ? '解除黑名單' : '加入黑名單' }}</button><button v-if="model.data.can_set_role" type="button" class="button outline" data-person-action="role" :disabled="model.busy">{{ model.data.person.role === 'deputy' ? '取消副團長' : '指定副團長' }}</button><button v-if="model.data.can_mute" type="button" class="button outline" data-person-action="mute" :disabled="model.busy">{{ model.data.person.muted ? '解除禁言' : '禁言' }}</button><button v-if="model.data.can_kick" type="button" class="button outline logout-button" data-person-action="kick" :disabled="model.busy">剔除遠征隊成員</button></div></template>
  <div v-else-if="model.kind === 'personConfirm' && model.pending" class="person-action-confirm"><p>{{ model.label }}</p><button class="button secondary" type="button" data-person-confirm-action :disabled="model.busy">{{ model.busy ? '處理中…' : '確認' }}</button><button class="button outline" type="button" data-person-cancel :disabled="model.busy">取消</button><p data-person-error role="alert">{{ model.error }}</p></div>
  <button v-else-if="model.kind === 'personRetry'" class="button outline full" type="button" data-person-retry>重新載入</button>
  <template v-else-if="model.kind === 'roomConfirm'"><p>{{ model.pending === 'delete' ? '解散後，隊內任務、地標與群聊會刪除，所有成員將退出，無法復原。' : '退出會撤回你未完成的任務、釋出已接任務並退出小隊；好友位置分享維持原設定。' }}</p><button type="button" class="button primary" data-room-confirm>{{ model.pending === 'delete' ? '確認解散' : '確認退出' }}</button><button type="button" class="button outline" data-room-cancel>取消</button></template>
  <template v-else-if="model.kind === 'catalog' || model.kind === 'owned'">
    <template v-for="room in model.items" :key="room.id"><article v-if="model.kind === 'owned'" class="room-item owned-room"><div><strong>{{ room.name }}</strong><small>{{ room.schedule }} · {{ room.venue_name }}</small></div><button class="button outline" data-action="manage-members" :data-id="room.id">管理</button><button class="button outline logout-button" data-action="delete-room" :data-id="room.id">刪除</button></article><button v-else class="room-item" :data-room-id="room.id"><span><strong>{{ room.name }}</strong><small>{{ room.schedule }} · {{ room.member_count }} 位夥伴</small></span><span>{{ room.joined ? '進入' : '加入' }} ›</span></button></template>
    <div v-if="!model.items.length" class="empty"><strong>{{ model.kind === 'owned' ? '還沒有建立的遠征隊' : '這個場館還沒有遠征隊' }}</strong>{{ model.kind === 'owned' ? '建立隊伍後，可在這裡管理。' : '可以先建立一支，讓同場的夥伴加入。' }}</div>
  </template>
  <div v-else-if="model.kind === 'error'" class="empty"><strong>暫時無法載入</strong>{{ model.error }}</div>
</template>
